async function orderChannel(url, onOrder) {
  const conn = await amqp.connect(url);
  const ch = await conn.createChannel();
  await ch.assertQueue('orders', { durable: true });
  await ch.consume('orders', msg => {                 // inbound
    if (!msg) return;
    onOrder(JSON.parse(msg.content.toString()));
    ch.ack(msg);
  });
  return { publish: order => ch.sendToQueue('orders',
      Buffer.from(JSON.stringify(order)), { persistent: true }) };
}
